const query = $input.first().json.query || {};
const dealId = Number(query.dealId || query.deal_id);
const claimedBy = String(query.claimedBy || query.user || '32598');
const reset = String(query.reset || '').toLowerCase() === 'true';

if (!dealId || isNaN(dealId)) {
  return [{
    json: {
      valido: false,
      motivo: "Parâmetro 'dealId' inválido ou ausente."
    }
  }];
}

return [{
  json: {
    valido: true,
    dealId: dealId,
    claimedBy: claimedBy,
    reset: reset,
    lockKey: `sdr_shark_lock_${dealId}`
  }
}];

const item = $input.first().json;
const count = Number(Object.values(item)[0] || 0);
const parse = $('Parse_Claim_Params').first().json;

return [{
  json: {
    is_winner: (count === 1),
    counter: count,
    dealId: parse.dealId,
    claimedBy: parse.claimedBy
  }
}];

