      margin-bottom: 16px;
      text-transform: uppercase;
    }
    h1 {
      color: #111827;
      font-size: 24px;
      font-weight: 800;
      margin: 0 0 10px 0;
    }
    p {
      color: #4b5563;
      font-size: 15px;
      line-height: 1.5;
      margin: 0 0 20px 0;
    }
    .deal-badge {
      background: #f3f4f6;
      padding: 12px 16px;
      border-radius: 10px;
      color: #1f2937;
      font-weight: 700;
      font-size: 16px;
      margin-bottom: 24px;
    }
    .btn-primary {
      display: block;
      padding: 14px 24px;
      background: #059669;
      color: #ffffff;
