      border-radius: 10px;
      font-weight: 700;
      font-size: 16px;
      box-shadow: 0 4px 14px rgba(5, 150, 105, 0.4);
      transition: background 0.2s;
    }
    .btn-primary:hover {
      background: #047857;
    }
    .redirect-timer {
      color: #9ca3af;
      font-size: 13px;
      margin-top: 14px;
